import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define ROWS_PER_BLOCK 32
#define K_TILE 4096
__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K, int numChunks) {
    int rowBlock = blockIdx.x;
    int rowBase = rowBlock * ROWS_PER_BLOCK;
    int warpId = threadIdx.x / warpSize;
    int lane = threadIdx.x % warpSize;
    int row = rowBase + warpId;
    extern __shared__ float sB[]; // K_TILE floats, reused across ROWS_PER_BLOCK rows and chunks
    float sum = 0.0f;
    for (int chunk = 0; chunk < numChunks; chunk++) {
        int chunkStart = chunk * K_TILE;
        int chunkEnd = chunkStart + K_TILE;
        if (chunkEnd > K) chunkEnd = K;
        int chunkLen = chunkEnd - chunkStart;
        if (chunkLen <= 0) continue;
        int chunkLen4 = chunkLen / 4;
        const float4* B4 = reinterpret_cast<const float4*>(B + chunkStart);
        float4* sB4 = reinterpret_cast<float4*>(sB);
        for (int i = threadIdx.x; i < chunkLen4; i += blockDim.x) {
            sB4[i] = B4[i];
        }
        for (int i = chunkLen4 * 4 + threadIdx.x; i < chunkLen; i += blockDim.x) {
            sB[i] = B[chunkStart + i];
        }
        __syncthreads();
        if (row < M) {
            const float* Arow = A + (size_t)row * K + chunkStart;
            const float4* Arow4 = reinterpret_cast<const float4*>(Arow);
            for (int i = lane; i < chunkLen4; i += warpSize) {
                float4 a = Arow4[i];
                float4 b = sB4[i];
                sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            }
            for (int i = chunkLen4 * 4 + lane; i < chunkLen; i += warpSize) {
                sum += Arow[i] * sB[i];
            }
        }
        __syncthreads(); // ensure all warps finish reading sB before it's overwritten
    }
    if (row >= M) return;
    unsigned mask = 0xffffffff;
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum += __shfl_down_sync(mask, sum, offset);
    if (lane == 0) C[row] = sum;
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());
    int numChunks = (K + K_TILE - 1) / K_TILE;
    int numRowBlocks = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    dim3 grid(numRowBlocks);
    int threads = ROWS_PER_BLOCK * 32;
    size_t smem = (size_t)K_TILE * sizeof(float);
    matvec_kernel<<<grid, threads, smem>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, numChunks
    );
    return C;
}
"""

matvec_cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=matvec_cpp_source,
    cuda_sources=matvec_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

